196	\toprule
197	\textbf{Variant} & \textbf{0v1} & \textbf{1v2} & \textbf{1v2 CI} & $\Kstar$ \\
198	\midrule
199	Instruct & 0.992 & 0.611 & [.602, .621] & 2 \\
